blocks.code:
ul {
  padding: 0;
  list-style: none;
}

li {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: #eff6ff;
  border-radius: 9999px;
}

a {
  display: block;   /* the link now fills a line and accepts width and margins */
  margin: 1rem 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
